package org.springframework.samples.petclinic.util;

import java.util.Locale;
import java.util.Map;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/**
 * Normalizes owner addresses into a canonical form, used both for storage and for comparing addresses.
 */
public final class AddressNormalizer {

    private static final Map<String, String> ABBREVIATIONS = Map.of(
        "ST", "STREET",
        "RD", "ROAD",
        "AVE", "AVENUE");

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");

    private AddressNormalizer() {
    }

    /**
     * Trims the address, collapses runs of whitespace into a single space, upper-cases it and expands
     * the whole-word abbreviations ST, RD and AVE (optionally followed by a '.') to STREET, ROAD and AVENUE.
     *
     * @param address the address as supplied
     * @return the normalized address, empty if the address is {@code null} or blank
     */
    public static String normalize(String address) {
        if (address == null || address.isBlank()) {
            return "";
        }
        return WHITESPACE.splitAsStream(address.strip().toUpperCase(Locale.ROOT))
            .map(AddressNormalizer::expand)
            .collect(Collectors.joining(" "));
    }

    private static String expand(String word) {
        String bare = word.endsWith(".") ? word.substring(0, word.length() - 1) : word;
        return ABBREVIATIONS.getOrDefault(bare, word);
    }
}
package org.springframework.samples.petclinic.rest.validation;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.util.AddressNormalizer;

/**
 * Determines which of the fields required to create an owner are missing or blank. The address is
 * checked in its normalized form, so an address that is blank after normalization counts as missing.
 */
public final class RequiredOwnerFields {

    private RequiredOwnerFields() {
    }

    /**
     * @param owner the owner fields from the request body
     * @return names of required fields that are missing or blank, in declaration order; empty if none
     */
    public static List<String> missingFields(OwnerFieldsDto owner) {
        Map<String, String> required = new LinkedHashMap<>();
        required.put("firstName", owner.getFirstName());
        required.put("lastName", owner.getLastName());
        required.put("address", AddressNormalizer.normalize(owner.getAddress()));
        required.put("city", owner.getCity());
        required.put("telephone", owner.getTelephone());
        List<String> missing = new ArrayList<>();
        required.forEach((field, value) -> {
            if (value == null || value.isBlank()) {
                missing.add(field);
            }
        });
        return missing;
    }
}
